import React from "react";
import { motion } from "framer-motion";

export default function Home() {
  return (
    <div className="bg-gray-50 min-h-screen flex flex-col items-center justify-center text-center px-6">
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        className="max-w-5xl"
      >
        <h1 className="text-4xl md:text-5xl font-extrabold text-blue-600 leading-tight">
          Your AI-powered Interview Coach
        </h1>
        <p className="mt-4 text-gray-700 text-lg md:text-xl max-w-2xl mx-auto">
          Practice mock interviews, receive real-time AI feedback, and improve your
          confidence — all in one platform.
        </p>

        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className="mt-8 bg-blue-600 text-white px-6 py-3 rounded-lg shadow-md hover:bg-blue-700 transition"
        >
          Start Practicing
        </motion.button>
      </motion.div>

      <motion.img
        src="https://cdn.pixabay.com/photo/2023/05/09/12/11/ai-7982206_960_720.png"
        alt="AI Interview Coach Illustration"
        className="mt-12 w-full max-w-lg drop-shadow-md rounded-xl"
        initial={{ opacity: 0, y: 40 }}
        whileInView={{ opacity: 1, y: 0 }}
        transition={{ duration: 1 }}
      />
    </div>
  );
}
